"""Analytic three-lobe stator and ribbed output hub around fixed motor interfaces."""
class SlimMountIntent(CohesiveLimbIntent):
 def parameters(self):
  g=self.g
  for name,value in {'sm_stator_mount_plane':53.5,'sm_stator_thickness':3,'sm_fastener_diametral_compensation':0,'sm_output_hole_diametral_compensation':0,'sm_output_head_diametral_compensation':0,'sm_hub_head_nominal_radius':3.8}.items():g.parameter(name,value)
  values={'sm_tie_radius':43.5,'sm_stator_outer_radius':40.5,'sm_stator_lobe_radius':4.5,'sm_stator_base_y':'sm_stator_mount_plane-sm_stator_thickness','sm_stator_thickness':3,'sm_stator_pad_thickness':1.5,'sm_stator_bore_radius':30,'sm_hub_base_y':5,'sm_hub_thickness':3,'sm_hub_corner_radius':5.5,'sm_hub_collar_radius':20,'sm_hub_shaft_radius':6,'sm_hub_tie_pad_radius':6,'sm_hub_tie_pad_thickness':1.5,'sm_hub_head_radius':'sm_hub_head_nominal_radius+sm_output_head_diametral_compensation/2','sm_hub_head_start_y':3.7,'sm_hub_head_depth':4.5,'sm_hub_rib_width':12,'sm_hub_rib_depth':4.5,'sm_hub_rib_length':20,'sm_hub_rib_center_radius':27,'sm_hub_rib_start_y':.5,'sm_hub_rib_radius':1.2,'sm_rotating_envelope_radius':48,'sm_tie_hole_radius':'lc_carrier_stator_hole+sm_fastener_diametral_compensation/2','sm_stator_pcd_radius':'lc_carrier_stator_pcd','sm_stator_hole_radius':'lc_carrier_stator_hole+sm_fastener_diametral_compensation/2','sm_output_pcd_radius':'lc_rs02_output_pcd_radius','sm_output_hole_radius':'lc_rs02_output_hole_radius+sm_output_hole_diametral_compensation/2','sm_stator_pad_y':'sm_stator_base_y+sm_stator_thickness','sm_hub_pad_y':'sm_hub_base_y+sm_hub_thickness'}
  for name,value in values.items():g.parameter(name,value,comment='Slim motor mount: independent structure or shared fixed RS02 vendor interface. Process compensation remains explicit; aluminum strength is unqualified.')
  g.parameter('sm_tie_count',3,'');g.parameter('sm_stator_tangent_angle','acos((sm_stator_outer_radius-sm_stator_lobe_radius)/sm_tie_radius)','deg')
 def profile(self,kind):
  self.parameters();g=self.g;c=self.c;plane=g.plane(c.xZConstructionPlane,'sm_stator_base_y' if kind=='stator' else 'sm_hub_base_y',kind+' structural datum');sk=c.sketches.add(plane);sk.name='Three tangent lobes' if kind=='stator' else 'Three rounded structural corners';sk.isComputeDeferred=True;origin=sk.originPoint;centers=[];ys={}
  for theta in [90,210,330]:
   x=f'sm_tie_radius*cos({theta} deg)';y=f'-sm_tie_radius*sin({theta} deg)';p=g.skeleton_point(sk,x,y);value=round(p.geometry.y,8);g.point_dimensions(sk,p,x,y if value not in ys else None)
   if value in ys:sk.geometricConstraints.addHorizontalPoints(ys[value],p)
   ys[value]=p;centers.append(p)
  arcs=[]
  if kind=='stator':
   for theta,center in zip([90,210,330],centers):
    start=f'-({theta} deg-sm_stator_tangent_angle)';end=f'-({theta} deg+sm_stator_tangent_angle)';lobe=g.driven_arc(sk,center,'sm_stator_lobe_radius',start,end,'Tie lobe');central=g.driven_arc(sk,origin,'sm_stator_outer_radius',end,f'-({theta+120} deg-sm_stator_tangent_angle)','Central tangent arc');arcs.extend([lobe,central])
  else:
   for theta,center in zip([90,210,330],centers):arcs.append(g.driven_arc(sk,center,'sm_hub_corner_radius',f'-({theta} deg-60 deg)',f'-({theta} deg+60 deg)','Rounded tie corner'))
  for i,(_,first,last) in enumerate(arcs):sk.sketchCurves.sketchLines.addByTwoPoints(last,arcs[(i+1)%len(arcs)][1])
  sk.isComputeDeferred=False;assert sk.profiles.count==1,(kind,sk.profiles.count);return sk
 def feature_pattern(self,feature,count,name):
  objects=core.ObjectCollection.create();objects.add(feature);inp=self.c.features.circularPatternFeatures.createInput(objects,self.c.yConstructionAxis);inp.quantity=self.g.value(count);inp.totalAngle=self.g.value('360 deg');inp.patternComputeOption=fusion.PatternComputeOptions.AdjustPatternCompute;f=self.c.features.circularPatternFeatures.add(inp);f.name=name;assert self.c.bRepBodies.count==1;return self.c.bRepBodies.item(0)
 def circular_seed(self,body,y,depth,radius,center_radius,theta,count,name,join=False):
  sk=self.circles(y,[(center_radius+f'*cos({theta} deg)',center_radius+f'*sin({theta} deg)',radius)],name+' seed');body=self.extrude_all(sk,depth,name+' seed',fusion.FeatureOperations.JoinFeatureOperation if join else fusion.FeatureOperations.CutFeatureOperation,body);feature=self.c.features.extrudeFeatures.item(self.c.features.extrudeFeatures.count-1);return self.feature_pattern(feature,count,name+' circular pattern')
 def stator(self):
  g=self.g;c=self.c;body=g.extrude(self.profile('stator'),'sm_stator_thickness','Single tangent-lobed stator plate').bodies.item(0);body=self.circular_seed(body,'sm_stator_pad_y','sm_stator_pad_thickness','sm_stator_lobe_radius','sm_tie_radius',90,'sm_tie_count','Integral tie compression pads',True)
  sk=self.circles('sm_stator_base_y-1 mm',[('0 mm','0 mm','sm_stator_bore_radius')],'Open motor center');body=self.extrude_all(sk,'sm_stator_thickness+2 mm','Open central stator bore',fusion.FeatureOperations.CutFeatureOperation,body)
  body=self.circular_seed(body,'sm_stator_base_y-1 mm','sm_stator_thickness+2 mm','sm_stator_hole_radius','sm_stator_pcd_radius',20,'lc_carrier_stator_bolt_count','Nine fixed motor mounting holes');body=self.circular_seed(body,'sm_stator_base_y-1 mm','sm_stator_thickness+sm_stator_pad_thickness+2 mm','sm_tie_hole_radius','sm_tie_radius',90,'sm_tie_count','Three structural tie clearances');assert c.bRepBodies.count==1;return body
 def hub(self):
  g=self.g;c=self.c;body=g.extrude(self.profile('hub'),'sm_hub_thickness','Rounded triangular output plate').bodies.item(0);sk=self.circles('0 mm',[('0 mm','0 mm','sm_hub_collar_radius')],'Integral motor-side collar');body=self.extrude_all(sk,'sm_hub_base_y','Broad output collar',fusion.FeatureOperations.JoinFeatureOperation,body)
  rib=g.box('sm_hub_rib_width','sm_hub_rib_depth','sm_hub_rib_length','0 mm','sm_hub_rib_start_y+sm_hub_rib_depth/2','sm_hub_rib_center_radius','Broad radial reinforcing rib');rib=g.round_edges(rib,'sm_hub_rib_radius','Accessible rib edge radii');before={b.entityToken for b in c.bRepBodies};objects=core.ObjectCollection.create();objects.add(rib);inp=c.features.circularPatternFeatures.createInput(objects,c.yConstructionAxis);inp.quantity=g.value('sm_tie_count');inp.totalAngle=g.value('360 deg');f=c.features.circularPatternFeatures.add(inp);f.name='Three broad radial ribs';ribs=[rib]+[b for b in c.bRepBodies if b.entityToken not in before];body=g.combine(body,ribs,fusion.FeatureOperations.JoinFeatureOperation,'Ribs joined over full plate contact areas')
  body=self.circular_seed(body,'sm_hub_pad_y','sm_hub_tie_pad_thickness','sm_hub_tie_pad_radius','sm_tie_radius',90,'sm_tie_count','Integral hub tie pads',True);sk=self.circles('-1 mm',[('0 mm','0 mm','sm_hub_shaft_radius')],'Open axial shaft passage');body=self.extrude_all(sk,'sm_hub_pad_y+sm_hub_tie_pad_thickness+2 mm','Through shaft passage',fusion.FeatureOperations.CutFeatureOperation,body)
  body=self.circular_seed(body,'0 mm','sm_hub_pad_y+sm_hub_tie_pad_thickness+3.5 mm','sm_output_hole_radius','sm_output_pcd_radius',0,'lc_rs02_output_bolt_count','Six fixed output bolt clearances');body=self.circular_seed(body,'sm_hub_head_start_y','sm_hub_head_depth','sm_hub_head_radius','sm_output_pcd_radius',0,'lc_rs02_output_bolt_count','Six accessible output head recesses');body=self.circular_seed(body,'0 mm','sm_hub_pad_y+sm_hub_tie_pad_thickness+1.5 mm','sm_tie_hole_radius','sm_tie_radius',90,'sm_tie_count','Three structural tie bores')
  sk=self.circles('-1 mm',[('0 mm','0 mm','sm_rotating_envelope_radius')],'Fixed rotating radial envelope');tool=g.extrude(sk,'sm_hub_pad_y+sm_hub_tie_pad_thickness+2.5 mm','Carrier radial clearance envelope').bodies.item(0);return g.combine(body,[tool],fusion.FeatureOperations.IntersectFeatureOperation,'Preserve the existing rotating carrier envelope')
